scripts.朱海对话.txt:
// 和朱海对话

	If ($Zhujiarenshen == 0) @Load0;
	If ($Zhujiarenshen == 1) @Load1;
	Return;
	
@Load0:	

	If ($Talkzhuhai == 0) @Talk0;
	If ($Talkzhuhai == 1) @Talk1;
	
@Talk0:	
	Say("朱海：姑娘擅闯民宅，意欲何为！"，0);
	Say("张琳心：我的朋友身受重伤，需要长白山的千年双头人参才能救他。听说您这里有一支……", 101);
	Say("朱海：有倒是有，不过双头人参是稀世珍宝，花了我不少银子才弄到，我与你素不相识，凭什么给你。", 0);
	Say("张琳心：我并不是贪图双头人参，只是我朋友命悬一线，等着人参活命，请你们发发慈悲……", 106);
	Say("朱海：哼，你朋友是生是死，与我有什么相干？", 0);
	Say("张琳心：难道你竟忍心见死不救？", 106);
	Say("朱海：少废话，没有好处的事情我从来不干，你走吧！", 0);
	
	Choose("抢不抢人参", "A 抢", "B 不抢", $qiang);
	If ($qiang == 0) @Choose0;
	If ($qiang == 1) @Choose1;

@Choose0:
	Say("张琳心：你……竟如此冷血！既如此，为了救独孤哥哥，我只有冒犯了！", 107);
	Say("朱海：想动武？哈哈哈哈！我朱家在长白山还没有怕过谁！", 0);
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("朱海",1);
	SetNpcRelation("朱夫人",1);
	SetNpcRelation("朱府家丁",1); 
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetNpcScript("朱海", "");
	SetNpcScript("朱夫人", "");
	SetNpcScript("朱府家丁", "");
	Assign($Talkzhuhai, 1);
	Return;

@Choose1:
	Assign($Talkzhuhai, 1);
	Return;
	
	
@Talk1:		
	Say("朱海：少废话，没有好处的事情我从来不干，你走吧！", 0);
	
	Choose("抢不抢人参", "A 抢", "B 不抢", $qiangmore);
	If ($qiangmore == 0) @Choose2;
	If ($qiangmore == 1) @Choose3;

@Choose2:
	
	Say("张琳心：你……竟如此冷血！既如此，为了救独孤哥哥，我只有冒犯了！", 107);
	Say("朱海：想动武？哈哈哈哈！我朱家在长白山还没有怕过谁！", 0);
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("朱海",1);
	SetNpcRelation("朱夫人",1);
	SetNpcRelation("朱府家丁",1); 
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetNpcScript("朱海", "");
	SetNpcScript("朱夫人", "");
	SetNpcScript("朱府家丁", "");
	Return;		
	
@Choose3:
	Return;	
	
		
		
@Load1:
	Return;

